import pytest

from bedrock_protocol import v1001, v2168

# generated by gophertunnel 6353c49:
# &packet.PlayerAction{EntityRuntimeID: 7, ActionType: 37, BlockPosition: protocol.BlockPos{1, 2, 3},
#   ResultPosition: protocol.BlockPos{4, 5, 6}, BlockFace: 2}
START_USING_ITEM = bytes.fromhex("074a020406080a0c04")

# generated by gophertunnel b8bd735:
# &packet.PlayerAction{EntityRuntimeID: 7, ActionType: 38, BlockPosition: protocol.BlockPos{1, 2, 3},
#   ResultPosition: protocol.BlockPos{4, 5, 6}, BlockFace: 2}
INTERNAL_UPDATE = bytes.fromhex("074c020406080a0c04")

GOLDENS = [
    pytest.param(
        v1001.PlayerActionPacket(
            runtime_id=7,
            action=v1001.PlayerActionType.START_USING_ITEM,
            pos=v1001.BlockPos(x=1, y=2, z=3),
            result_pos=v1001.BlockPos(x=4, y=5, z=6),
            face=2,
        ),
        START_USING_ITEM,
        id="v1001-start-using-item",
    ),
    pytest.param(
        v2168.PlayerActionPacket(
            runtime_id=7,
            action=v2168.PlayerActionType.START_USING_ITEM,
            pos=v2168.BlockPos(x=1, y=2, z=3),
            result_pos=v2168.BlockPos(x=4, y=5, z=6),
            face=2,
        ),
        START_USING_ITEM,
        id="v2168-start-using-item",
    ),
    pytest.param(
        v2168.PlayerActionPacket(
            runtime_id=7,
            action=v2168.PlayerActionType.INTERNAL_UPDATE,
            pos=v2168.BlockPos(x=1, y=2, z=3),
            result_pos=v2168.BlockPos(x=4, y=5, z=6),
            face=2,
        ),
        INTERNAL_UPDATE,
        id="v2168-internal-update",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168])
def test_player_action_is_packet_36(version):
    assert version.packets[36] is version.PlayerActionPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_player_action_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_player_action_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize(
    ("member", "value"),
    [
        pytest.param(v1001.PlayerActionType.COUNT, 38, id="v1001-count"),
        pytest.param(v2168.PlayerActionType.INTERNAL_UPDATE, 38, id="v2168-internal-update"),
        pytest.param(v2168.PlayerActionType.COUNT, 39, id="v2168-count"),
    ],
)
def test_2168_appends_internal_update_where_1001_keeps_its_count_sentinel(member, value):
    assert member == value


def test_v1001_reads_action_38_as_its_count_sentinel():
    assert v1001.PlayerActionPacket.from_bytes(INTERNAL_UPDATE) == v1001.PlayerActionPacket(
        runtime_id=7,
        action=v1001.PlayerActionType.COUNT,
        pos=v1001.BlockPos(x=1, y=2, z=3),
        result_pos=v1001.BlockPos(x=4, y=5, z=6),
        face=2,
    )
